function randomGame() {
  const r = state.route;
  let pool;
  if (r.model && r.harness) pool = buildsOfModel(r.model).filter((b) => hzBucketOf(b) === r.harness);
  else if (r.model) pool = buildsOfModel(r.model);
  else pool = state.builds.filter((b) => modelVisible(modelKey(b.model) || "misc"));
  pool = pool.filter((b) => b.status === "playable" && b.entry);
  if (!pool.length) { toastMsg("no playable builds in this view"); return; }
  openOverlay(pool[Math.floor(Math.random() * pool.length)].id);
}
$("#random-btn").addEventListener("click", randomGame);
$("#ov-close").addEventListener("click", closeOverlay);
$("#ov-backdrop").addEventListener("click", closeOverlay);
$("#back-btn").addEventListener("click", () => {
  destroyLive();
  if (state.route.harness) goRoute(state.route.model);
  else goRoute();
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && !$("#overlay").hidden) { closeOverlay(); return; }
  // overlay game switcher (item 27): ←/→ walks the last viewed list
  if (!$("#overlay").hidden && (e.key === "ArrowLeft" || e.key === "ArrowRight")) {
    const ids = state._lastList || [];
    const idx = ids.indexOf(state.overlayId);
    if (idx === -1 || ids.length < 2) return;
    const next = ids[(idx + (e.key === "ArrowRight" ? 1 : ids.length - 1)) % ids.length];
    if (next && next !== state.overlayId) { destroyLive(); openOverlay(next); }
    return;
  }
  const typing = /^(INPUT|TEXTAREA)$/.test(document.activeElement?.tagName || "");
  if (typing || !$("#overlay").hidden) return;
  if (e.key === "Escape") {
    if (state.query) { $("#search").value = ""; setSearchQuery(""); }
    else if (state.route.harness) goRoute(state.route.model);
    else if (state.route.model) goRoute();
  } else if (e.key === "Backspace" && !$("#search").value) {
    if (state.route.harness) goRoute(state.route.model);
    else if (state.route.model) goRoute();
  } else if (e.key === "r" || e.key === "R") {
    randomGame();
  } else if (e.key === "g" || e.key === "G") {
    const btn = document.querySelector(`#viewtoggle button[data-view="${state.view === "grid" ? "strip" : "grid"}"]`);
    btn?.click();
  }
});

/* magnetic grid (item 25) — cards lean toward the cursor, spring back */
(function magneticGrid() {
  if (REDUCED || !FINE) return;
  let mx = -1, my = -1, raf = 0;
  function apply() {
    raf = 0;
    grid.querySelectorAll(".card").forEach((card) => {
      if (card.classList.contains("skeleton")) return;
      const r = card.getBoundingClientRect();
      if (r.bottom < 0 || r.top > innerHeight) return;
      if (mx < 0) {
        if (card.style.getPropertyValue("--magx")) { card.style.removeProperty("--magx"); card.style.removeProperty("--magy"); }
        return;
      }
      const dx = mx - (r.left + r.width / 2);
      const dy = my - (r.top + r.height / 2);
      const d = Math.hypot(dx, dy) || 1;
      const pull = Math.max(0, 1 - d / 240) * 2.5;
      card.style.setProperty("--magx", ((dx / d) * pull).toFixed(2) + "px");
      card.style.setProperty("--magy", ((dy / d) * pull).toFixed(2) + "px");
    });
  }
  grid.addEventListener("pointermove", (e) => {
    mx = e.clientX; my = e.clientY;
    if (!raf) raf = requestAnimationFrame(apply);
  });
  grid.addEventListener("pointerleave", () => {
    mx = my = -1;
    if (!raf) raf = requestAnimationFrame(apply);
  });
})();

/* favicon + title exhibit count (item 33) */
let favCanvas = null;
function updateExhibitFavicon() {
  try {
    const count = state.builds.length;
    document.title = `${count} EXHIBITS \u00B7 EpicBench`;
    if (!favCanvas) {
      favCanvas = document.createElement("canvas");
      favCanvas.width = favCanvas.height = 64;
    }
    const c = favCanvas.getContext("2d");
    c.clearRect(0, 0, 64, 64);
    c.fillStyle = "#04060c";
    c.beginPath();
    c.arc(32, 32, 30, 0, Math.PI * 2);
    c.fill();
    c.strokeStyle = "#22d3ee";
    c.lineWidth = 3;
    c.stroke();
    c.fillStyle = "#e6f5ff";
    c.textAlign = "center";
    c.textBaseline = "middle";
    c.font = `700 ${count > 99 ? 18 : count > 9 ? 22 : 26}px Rajdhani, sans-serif`;
    c.fillText(String(count), 32, 34);
    let link = document.querySelector("link[rel='icon']");
    if (!link) {
      link = document.createElement("link");
      link.rel = "icon";
      document.head.appendChild(link);
    }
    link.href = favCanvas.toDataURL("image/png");
  } catch { /* cosmetic */ }
}
